"""Object model for the Mosaiq QCL (Quality Control List) tab and common controls."""

import objectmaphelper
from .mosaiq_core_objects import MosaiqCoreObjects

class MosaiqQCLObjects:

    QCL_Tab = MosaiqCoreObjects.tabBar_TabItem_QCL
    QCL_Window = {"text": objectmaphelper.Wildcard("Quality Check List Tasks*"), "type": "Window"} # used
    QCL_Dialog = {"text": objectmaphelper.Wildcard("Quality Check List Tasks*"), "type": "Dialog"}
    QCL_Task_Window = {"text": "Quality Check List Task", "type": "Window"}

    # The QCL grid uses DevExpress accessibility objects (confirmed via Object Spy: "Data Panel",
    # role=Client, class=DevExpress.Accessibility.BaseAccessible...), unlike the Orders grid which
    # is an owner-drawn native control. This matches the Data Panel -> Row -> Cell pattern used by
    # the other Mosaiq grids (Patient List, D&I, Staff).
    # The grid container itself is confirmed as "gridQCLTask" (WindowsFormsControl), holding both
    # the Header Panel and Data Panel as sibling accessible objects.

    QCL_Grid_Container = {"class": "Impac.Mosaiq.UI.Controls.ImpacGrids.ImpacGrid","container": QCL_Window,"name": "gridQCLTask","type": "WindowsFormsControl"}
    QCL_Header_Panel = {"container": QCL_Grid_Container,"name": "Header Panel","role": "Client","type": "WindowsFormsAccessibleObject"} #used
    QCL_Data_Panel = {"container": QCL_Grid_Container,"name": "Data Panel","role": "Client","type": "WindowsFormsAccessibleObject"} # used
    QCL_Row = {"container": QCL_Data_Panel,"role": "Row", "type": "WindowsFormsAccessibleObject"} # used
    QCL_Cell = {"container": QCL_Row,"role": "Cell", "type": "WindowsFormsAccessibleObject"}

    # Kept as a fallback only - the Object Spy evidence shows QCL is NOT an owner-drawn ClaList
    # control like Orders, so this is unlikely to be needed.
    QCL_Native_Grid_Controls = {"container": MosaiqCoreObjects.mOSAIQ_Main_Window,"class": objectmaphelper.Wildcard("ClaList*"),"type": "WindowsControl"} # used

    #Add_Button = {"container": QCL_Window, "text": "Add", "type": "Button"}
    #Change_Button = {"container": QCL_Window, "text": "Change", "type": "Button"}
    #Delete_Button = {"container": QCL_Window, "text": "Delete", "type": "Button"}
    Close_Button = {"container": QCL_Window, "name": "Close", "role": "PushButton", "type": "WindowsFormsAccessibleObject"} #used
    #Apply_Button = {"container": QCL_Window, "text": "Apply", "type": "Button"}
    #Clear_Button = {"container": QCL_Window, "text": "Clear", "type": "Button"}
    #Cancel_Button = {"container": ':Quality Check List Task_WindowsFormsControl', "text": "Cancel", "type": "Button"}

    # Department_Value_detail = {"container": ':Quality Check List Task_Window', "occurrence": "5", "type": "Edit"}
    QCL_Detail_Window = {"text": objectmaphelper.Wildcard("Quality Check List Task*"), "type": "Window"}
    Description_Label_detail = {"container": QCL_Detail_Window,"name": "Description","role": "Text","type": "WindowsFormsAccessibleObject"}
 
    #Description_Value_detail = {
    #    "container": QCL_Detail_Window,
    #    "name": "tbDescription",
    #    "type": "WindowsFormsControl",
    #}

    Description_Value_detail = {"container": QCL_Task_Window,"name": "teDescription","type": "WindowsFormsControl"} #used
    Inactive_CheckBox_detail = {"container": QCL_Task_Window,"class": "DevExpress.XtraEditors.CheckEdit","name": "ceInactive", "type": "WindowsFormsControl"}



